package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.util.HashSet;
import java.util.List;

import org.eclipse.rdf4j.query.QueryParseOptions;
import org.junit.jupiter.api.Test;

class DataBlockParseOptionsSerializationTest {
	@Test
	void insertPolicyIsPartOfEqualityAndHashKeysWithoutChangingRawSource() {
		String raw = "\r\n INSERT DATA { <_:fixed> <urn:p> <urn:o> } \r\n";
		InsertData defaultInsert = new InsertData(raw);
		InsertData strictInsert = new InsertData(raw);
		strictInsert.setParseOptions(QueryParseOptions.STRICT);

		assertThat(defaultInsert.getDataBlock()).isEqualTo(raw);
		assertThat(strictInsert.getDataBlock()).isEqualTo(raw);
		assertThat(new HashSet<>(List.of(defaultInsert, strictInsert))).hasSize(2);
		assertThat(strictInsert.clone()).isEqualTo(strictInsert);
		assertThat(strictInsert.clone().hashCode()).isEqualTo(strictInsert.hashCode());
	}

	@Test
	void deletePolicyIsPartOfEqualityAndHashKeysWithoutChangingRawSource() {
		String raw = "\r\n DELETE DATA { <_:fixed> <urn:p> <urn:o> } \r\n";
		DeleteData defaultDelete = new DeleteData(raw);
		DeleteData strictDelete = new DeleteData(raw);
		strictDelete.setParseOptions(QueryParseOptions.STRICT);

		assertThat(defaultDelete.getDataBlock()).isEqualTo(raw);
		assertThat(strictDelete.getDataBlock()).isEqualTo(raw);
		assertThat(new HashSet<>(List.of(defaultDelete, strictDelete))).hasSize(2);
		assertThat(strictDelete.clone()).isEqualTo(strictDelete);
		assertThat(strictDelete.clone().hashCode()).isEqualTo(strictDelete.hashCode());
	}

	@Test
	void strictPolicyAndSourceOffsetsSurviveSerializationAndCloning() throws Exception {
		InsertData insert = new InsertData("<urn:s> <urn:p> <urn:o> .");
		insert.setParseOptions(QueryParseOptions.STRICT);
		insert.setLineNumberOffset(4);
		DeleteData delete = new DeleteData("<urn:s> <urn:p> <urn:o> .");
		delete.setParseOptions(QueryParseOptions.STRICT);
		delete.setLineNumberOffset(9);

		InsertData restoredInsert = roundTrip(insert, InsertData.class);
		DeleteData restoredDelete = roundTrip(delete, DeleteData.class);

		assertThat(restoredInsert.getDataBlock()).isEqualTo(insert.getDataBlock());
		assertThat(restoredInsert.getParseOptions()).isEqualTo(QueryParseOptions.STRICT);
		assertThat(restoredInsert.getLineNumberOffset()).isEqualTo(4);
		assertThat(restoredDelete.getDataBlock()).isEqualTo(delete.getDataBlock());
		assertThat(restoredDelete.getParseOptions()).isEqualTo(QueryParseOptions.STRICT);
		assertThat(restoredDelete.getLineNumberOffset()).isEqualTo(9);
		assertThat(insert.clone().getParseOptions()).isEqualTo(QueryParseOptions.STRICT);
		assertThat(insert.clone().getLineNumberOffset()).isEqualTo(4);
		assertThat(new InsertData("").clone().getParseOptions()).isEqualTo(QueryParseOptions.DEFAULT);
	}

	private static <T> T roundTrip(T value, Class<T> type) throws IOException, ClassNotFoundException {
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		try (ObjectOutputStream output = new ObjectOutputStream(bytes)) {
			output.writeObject(value);
		}
		try (ObjectInputStream input = new ObjectInputStream(new ByteArrayInputStream(bytes.toByteArray()))) {
			return type.cast(input.readObject());
		}
	}
}
